var checkIfInstanceOf = function(obj, classFunction) {
    // Anything that is not a function cannot be a class; null/undefined have no prototype chain
    if (obj === null || obj === undefined || typeof classFunction !== 'function') {
        return false;
    }
    // Object(obj) boxes primitives (5 -> Number object) so they have a prototype chain
    let proto = Object.getPrototypeOf(Object(obj));
    while (proto !== null) {
        if (proto === classFunction.prototype) {
            return true;
        }
        proto = Object.getPrototypeOf(proto);
    }
    return false;
};
